import { defineConfig, mergeConfig } from 'vitest/config';

import { vitestCommonConfig } from '../../vitest.shared';

export default mergeConfig(
  vitestCommonConfig,
  defineConfig({
    // Add custom config here
  })
);

export const getVersionSpecifier = (addon: string) => {
  const groups = /^(@{0,1}[^@]+)(?:@(.+))?$/.exec(addon);
  if (groups) {
    return [groups[1], groups[2]] as const;
  }
  return [addon, undefined] as const;
};

const checkInstalled = (addonName: string, main: StorybookConfigRaw) => {
  const existingAddon = main.addons?.find((entry: string | { name: string }) => {
    const name = typeof entry === 'string' ? entry : entry.name;
    return name?.endsWith(addonName);
  });
  return !!existingAddon;
};

function isValidVersion(version: string) {
  return SemVer.valid(version) || version.match(/^\d+$/);
}

export async function migrate(migration: any, { glob, dryRun, list, rename, parser }: CLIOptions) {
  if (list) {
    listCodemods().forEach((key: any) => logger.log(key));
  } else if (migration) {
    await runCodemod(migration, { glob, dryRun, logger, rename, parser });
  } else {
    throw new Error('Migrate: please specify a migration name or --list');
  }
}

async function promptSelectedTemplate(choices: Choice[]): Promise<Choice | null> {
  // using any here as the types are too strict
  const selected = await prompt.select<any>({
    message: 'Select a template',
    options: choices.map(toChoices),
  });
  return selected as Choice;
}

export interface PostinstallOptions {
  packageManager: PackageManagerName;
  configDir: string;
  logger: typeof nodeLogger;
  prompt: typeof prompt;
  yes?: boolean;
  skipInstall?: boolean;
  /**
   * Skip all dependency management (collecting, adding to package.json, installing). Used when the
   * caller (e.g., init command) has already handled dependencies.
   */
  skipDependencyManagement?: boolean;
}

export const getVersionSpecifier = (addon: string) => {
  const groups = /^(@{0,1}[^@]+)(?:@(.+))?$/.exec(addon);
  if (groups) {
    return [groups[1], groups[2]] as const;
  }
  return [addon, undefined] as const;
};

constructor(
    readonly packageManager: JsPackageManager,
    private readonly commandOptions: CommandOptions,
    private readonly addonVitestService = new AddonVitestService(packageManager),
    private readonly telemetryService = new TelemetryService(commandOptions.disableTelemetry)
  ) {}

private getAddonsWithInstructions(addons: string[]): string[] {
    return addons.filter((addon) => ADDON_INSTALLATION_INSTRUCTIONS[addon]);
  }

export const executeAddonConfiguration = ({
  packageManager,
  options,
  ...rest
}: ExecuteAddonConfigurationParams & {
  packageManager: JsPackageManager;
  options: CommandOptions;
}) => {
  return new AddonConfigurationCommand(packageManager, options).execute(rest);
};

async execute({ storybookCommand }: ExecuteFinalizationParams): Promise<void> {
    // Update .gitignore
    await this.updateGitignore();

    const errors = ErrorCollector.getErrors();

    if (errors.length > 0) {
      await this.printFailureMessage(storybookCommand);
    } else {
      this.printSuccessMessage(storybookCommand);
    }
  }

private async printFailureMessage(storybookCommand?: string | null): Promise<void> {
    logger.warn(
      'Storybook setup completed, but some non-blocking errors occurred. Please check the log file below for details.'
    );
    this.printNextSteps(storybookCommand);

    try {
      const logFile = await logTracker.writeToFile(this.logfile);
      logger.warn(`Debug logs are written to: ${logFile}`);
    } catch {}
  }

private printSuccessMessage(storybookCommand?: string | null): void {
    logger.step(CLI_COLORS.success('Storybook was successfully installed in your project!'));
    this.printNextSteps(storybookCommand);
  }

private printNextSteps(storybookCommand?: string | null): void {
    if (storybookCommand) {
      logger.log(
        `To run Storybook manually, run ${CLI_COLORS.cta(storybookCommand)}. CTRL+C to stop.`
      );
    }

